#define KM_KPV__CTRL_REG__RSVD_31_4_bm 0xfffffff0
#define KM_KPV__CTRL_REG__RSVD_31_4_bp 4
#define KM_KPV__CTRL_REG__RSVD_31_4_bw 28
#define KM_KPV__CTRL_REG__RSVD_31_4_reset 0x0

